export async function processWebhook(
  eventId: string,
  handle: () => Promise<void>,
) {
  if (processedWebhookIds.has(eventId)) return false;

  const existing = inFlightWebhooks.get(eventId);
  if (existing) {
    await existing;
    return false;
  }

  const processing = Promise.resolve().then(() => handle());
  inFlightWebhooks.set(eventId, processing);

  try {
    await processing;
    if (inFlightWebhooks.get(eventId) === processing) {
      processedWebhookIds.add(eventId);
    }
    return true;
  } finally {
    if (inFlightWebhooks.get(eventId) === processing) {
      inFlightWebhooks.delete(eventId);
    }
  }
}

export function clearProcessedWebhooks() {
  processedWebhookIds.clear();
  inFlightWebhooks.clear();
}

