const values: string[] = [];
let value = "";
let inQuotes = false;
let quoted = false;

for (let index = 0; index < row.length; index += 1) {
  const character = row[index];

  if (inQuotes) {
    if (character === '"') {
      if (row[index + 1] === '"') {
        value += '"';
        index += 1;
      } else {
        inQuotes = false;
      }
    } else {
      value += character;
    }
  } else if (character === '"' && value.length === 0) {
    inQuotes = true;
    quoted = true;
  } else if (character === ",") {
    values.push(quoted ? value : value.trim());
    value = "";
    quoted = false;
  } else {
    value += character;
  }
}

values.push(quoted ? value : value.trim());
return values;

