export function normalizeStorageKey(value: string): string | null {
  let decodedValue: string;

  try {
    decodedValue = decodeURIComponent(value);
  } catch {
    return null;
  }

  const normalizedValue = decodedValue.replaceAll("\\", "/");

  if (normalizedValue.startsWith("/") || /^[A-Za-z]:\//.test(normalizedValue)) {
    return null;
  }

  const segments: string[] = [];

  for (const segment of normalizedValue.split("/")) {
    if (!segment || segment === ".") {
      continue;
    }

    if (segment === "..") {
      return null;
    }

    segments.push(segment);
  }

  return segments.length > 0 ? segments.join("/") : null;
}

