      if (pendingProjectLoads.get(id) === projectLoad) {
        pendingProjectLoads.delete(id);
      }
      throw error;
    },
  );

  pendingProjectLoads.set(id, projectLoad);
  return projectLoad;
}

export function clearProjectCache() {
  projectCache.clear();
  pendingProjectLoads.clear();
}
